      // Category 17: රංගාලෝකය, අංගරචනය සහ වේදිකා පරිපාලනය
      SubjectMasterCategory(
        id = "dance_cat_17",
        categoryNumber = 17,
        titleSinhala = "රංගාලෝකය, අංගරචනය සහ වේදිකා පරිපාලනය",
        icon = "💡",
        color = Color(0xFFF43F5E),
        summary = "වේදිකා ආලෝකකරණය, අංගරචනය (Make-up), ශබ්ද පරිපාලනය සහ වේදිකා කළමනාකරණය.",
